47	    const systemMdResolution = resolvePathFromEnv(
48	      process.env['GEMINI_SYSTEM_MD'],
49	    );
50	
51	    const interactiveMode =
52	      interactiveOverride ?? context.config.isInteractive();
53	    const approvalMode =
